%% Step 1: Define symbolic variables
syms x t k lambda u(x, t) X(x) T(t)
%% Step 2: Define the PDE
PDE = (1/k) * diff(u, t) == diff(u, x, 2);
%% Step 3: Using separation of Variables
u(x, t) = X(x) * T(t);
%% Step 4: Substituting u(x,t) and dividing the PDE with u(x,t) 
PDE_sep = subs(PDE, u, X(x)*T(t));
PDE_sep = PDE_sep / (X(x) * T(t));
%% Step 5: Separating the two ODE's obtained
(1/k) * diff(T, t) / T == diff(X, x, 2) / X;
eqT = (1/k) * diff(T, t) == lambda * T;
eqX = diff(X, x, 2) == lambda * X;
%% Step 6: Solving the two ODE's 
T_sol = dsolve(eqT)
X_sol = dsolve(eqX)
%% Step 7: Combining the two solutions
u_sol = simplify(X_sol * T_sol)

