%% Step 1: Define symbolic variables
syms x y lambda u(x, y) X(x) Y(y)
%% Step 2: Define the PDE
PDE = 3 * diff(u, x) + 2 * diff(u, y) == 0;
%% Step 3: Using separation of Variables
u(x, y) = X(x) * Y(y);
%% Step 4: Substituting u(x,y) and dividing the PDE with u(x,y) 
PDE_sep = subs(PDE, u, X(x) * Y(y));
PDE_sep = PDE_sep / (X(x) * Y(y));
%% Step 5: Separating the two ODE's obtained
- 2 * diff(Y, y) / Y == 3 * diff(X, x) / X;
eqY = - 2 * diff(Y, y) == lambda * Y;
eqX = 3 * diff(X, x) == lambda * X;
%% Step 6: Solving the two ODE's 
Y_sol = dsolve(eqY)
X_sol = dsolve(eqX)
%% Step 7: Combining the two solutions
u_sol = simplify(X_sol * Y_sol)

